-- Replace the 20 sample profiles (sample-01 ... sample-20@example.com) with the new set.
-- Run in Supabase SQL Editor (alumni-hub). One statement: all-or-nothing.
-- Only rows with sample-XX@example.com emails are replaced; real form responses are untouched.
--
-- Each new profile gets:
--   raw_answers: the free-text answers + checkbox answers in the form's exact wording
--   tags: the tags written for each profile (the "both" tags from since/impact are counted
--         as interests). Saved as completed with model = 'expected-tags (no LLM call)',
--         so search works right away. To have the LLM tag them instead, run block 4 of
--         004_samples_and_search.sql, then the worker.

with removed as (
  -- any old sample row that isn't one of the 20 new emails
  delete from public.alumni_intake_responses
  where email like 'sample-%@example.com'
    and email not in (select format('sample-%s@example.com', lpad(n::text, 2, '0')) from generate_series(1, 20) n)
  returning id
)
insert into public.alumni_intake_responses
  (email, full_name, source_response_id, raw_answers, tags, source, submitted_at,
   tagging_status, evidence, model, taxonomy_version, tagged_at)
select v.email, v.full_name, v.response_id, v.raw, v.tags, 'sample', now(),
       'completed', '{}'::jsonb, 'expected-tags (no LLM call)', 'sample-profiles-v2', now()
