) as v (email, full_name, response_id, raw, tags)
-- same email as an old sample: overwrite that row completely
on conflict (email) do update set
  full_name = excluded.full_name, source_response_id = excluded.source_response_id,
  raw_answers = excluded.raw_answers, tags = excluded.tags, source = excluded.source,
  submitted_at = excluded.submitted_at, revision = public.alumni_intake_responses.revision + 1,
  tagging_status = 'completed', attempts = 0, lease_token = null, lease_until = null,
  evidence = excluded.evidence, model = excluded.model, taxonomy_version = excluded.taxonomy_version,
  prompt_version = null, fingerprint = null, usage = null, last_error = null,
  tagged_at = now(), updated_at = now();

-- Check: should show 20 new samples, all completed.
select count(*) as samples,
       count(*) filter (where tagging_status = 'completed') as tagged,
       string_agg(full_name, ', ' order by email) as names
from public.alumni_intake_responses
where email like 'sample-%@example.com';
